# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#065f46">TENVİN VE SAKİN NUNUN HÂLLERİ: İDGAM KAVRAMI VE ÇEŞİTLERİ</text>\n  <rect x="22" y="42" width="656" height="40" rx="8" fill="#064e3b"/>\n  <text x="350" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#ecfdf5">İDGAM HARFLERİ (6 HARF — يَرْمَلُونَ / YERMELÛNE):   ي - ر - م - ل - و - ن</text>\n  <rect x="22" y="92" width="320" height="125" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="114" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">1. İDGAM-I MEAL-GUNNE (GUNNELİ İDGAM)</text>\n  <text x="34" y="138" font-size="11.5" font-weight="bold" fill="#047857">• Harfleri (4 Harf — يَمْنُو / YEMNÛ):  ي - م - ن - و</text>\n  <text x="34" y="160" font-size="10.8" fill="#064e3b">• Tenvin veya sakin nundan sonra bu 4 harften biri</text>\n  <text x="42" y="176" font-size="10.8" fill="#064e3b">farklı kelimenin başında gelirse idgam yapılır.</text>\n  <text x="34" y="198" font-size="10.8" font-weight="bold" fill="#065f46">• Okunuş: Sakin nun katılır ve 1,5 elif gunne tutulur.</text>\n  <rect x="358" y="92" width="320" height="125" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="114" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. İDGAM-I BİLA-GUNNE (GUNNESİZ İDGAM)</text>\n  <text x="370" y="138" font-size="11.5" font-weight="bold" fill="#1d4ed8">• Harfleri (2 Harf — ل ve ر):  ل (Lam) - ر (Ra)</text>\n  <text x="370" y="160" font-size="10.8" fill="#1e3a8a">• Tenvin veya sakin nundan sonra Lam (ل) veya Ra (ر)</text>\n  <text x="378" y="176" font-size="10.8" fill="#1e3a8a">harfi geldiğinde nun sesi tamamen bu harflere katılır.</text>\n  <text x="370" y="198" font-size="10.8" font-weight="bold" fill="#1e40af">• Okunuş: Gunne (geniz sesi) yapılmadan şeddeli okunur.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">İdgam: Bir harfi diğer harfin içinde eriterek ikinci harfi şeddeli gibi okumaktır (iki ayrı kelime arasında olur).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">İDGAM ÖRNEKLERİ VE AYNI KELİMEDE İZHAR-I KELİME-İ VÂHİDE İSTİSNASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#92400e">KUR\'AN-I KERİM\'DEN İDGAM ÖRNEKLERİ</text>\n  <text x="34" y="90" font-size="11" font-weight="bold" fill="#b45309">• İdgam-ı Meal-Gunne (ي - م - ن - و):</text>\n  <text x="42" y="110" font-size="10.8" fill="#78350f">مَنْ يَعْمَلْ (mey-ya\'mel) | مِنْ مَالٍ (mim-mâlin)</text>\n  <text x="42" y="128" font-size="10.8" fill="#78350f">مِنْ نِعْمَةٍ (min-ni\'metin) | مِنْ وَاقٍ (miv-vâk)</text>\n  <text x="34" y="154" font-size="11" font-weight="bold" fill="#b45309">• İdgam-ı Bila-Gunne (ل - ر):</text>\n  <text x="42" y="174" font-size="10.8" fill="#78350f">مِنْ لَدُنْهُ (mil-ledünhü) | هُدًى لِلْمُتَّقِينَ (hüdel-lilmüttakîn)</text>\n  <text x="42" y="194" font-size="10.8" fill="#78350f">مِنْ رَبِّهِمْ (mir-rabbihim) | غَفُورٌ رَحِيمٌ (ğafûrur-rahîm)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#991b1b">ÖNEMLİ İSTİSNA: İZHAR-I MUTLAK (4 KELİME)</text>\n  <text x="370" y="88" font-size="10.5" fill="#7f1d1d">Sakin nun ile (ي veya و) harfi AYNI KELİME içinde</text>\n  <text x="370" y="104" font-size="10.5" fill="#7f1d1d">yan yana gelirse anlam bozulmasın diye İDGAM YAPILMAZ,</text>\n  <text x="370" y="120" font-size="10.5" font-weight="bold" fill="#991b1b">açıkça (izhar ile) okunur (İzhar-ı Kelime-i Vâhide):</text>\n  <text x="380" y="144" font-size="11" font-weight="bold" fill="#7f1d1d">1. دُنْيَا (dünyâ) — Dünya</text>\n  <text x="380" y="164" font-size="11" font-weight="bold" fill="#7f1d1d">2. بُنْيَانٌ (bünyânün) — Bina / Yapı</text>\n  <text x="380" y="184" font-size="11" font-weight="bold" fill="#7f1d1d">3. صِنْوَانٌ (sınvânün) — Çatallı hurma ağacı</text>\n  <text x="380" y="204" font-size="11" font-weight="bold" fill="#7f1d1d">4. قِنْوَانٌ (kınvânün) — Hurma salkımları</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İdgam kuralının gerçekleşmesi için sakin nun (veya tenvin) birinci kelimenin sonunda, idgam harfi ikinci kelimenin başında olmalıdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">DÖRDÜNCÜ HÂL: İKLAB KURALI VE TENVİN/SAKİN NUN ÖZET TABLOSU</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">İKLAB KURALI (DÖNÜŞTÜRME — TEK HARF: ب)</text>\n  <text x="34" y="90" font-size="11.2" font-weight="bold" fill="#7e22ce">• Harfi: Yalnızca ب (Bâ) harfidir.</text>\n  <text x="34" y="112" font-size="10.8" fill="#581c87">• Tenvin veya sakin nundan sonra ب (bâ) harfi gelirse</text>\n  <text x="42" y="128" font-size="10.8" fill="#581c87">nun sesi halis م (mim) sesine çevrilir.</text>\n  <text x="34" y="150" font-size="10.8" font-weight="bold" fill="#6b21a8">• Okunuş: Dudaklar hafifçe değdirilip 1,5 elif gunne</text>\n  <text x="42" y="166" font-size="10.8" font-weight="bold" fill="#6b21a8">tutularak mim sesiyle okunur (Mushaflarda küçük م konur).</text>\n  <text x="34" y="190" font-size="10.8" fill="#581c87">• Örnekler: مِنْ بَعْدِ (mim-ba\'di) | سَمِيعٌ بَصِيرٌ (semî\'um-basîr)</text>\n  <text x="42" y="208" font-size="10.8" fill="#581c87">أَنْبِئْهُمْ (embi\'hüm) | لَيُنْبَذَنَّ (leyümbezenne)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#166534">TENVİN VE SAKİN NUNUN 5 HÂLİ (28 HARF DAĞILIMI)</text>\n  <text x="370" y="90" font-size="10.8" fill="#14532d">1. <tspan font-weight="bold">İzhar (6 Boğaz Harfi):</tspan> ء هـ ع ح غ خ (Açık okunur)</text>\n  <text x="370" y="114" font-size="10.8" fill="#14532d">2. <tspan font-weight="bold">İhfa (15 Harf):</tspan> ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك</text>\n  <text x="370" y="138" font-size="10.8" fill="#14532d">3. <tspan font-weight="bold">İdgam-ı Meal-Gunne (4 Harf — يَمْنُو):</tspan> ي م ن و (Gunneli)</text>\n  <text x="370" y="162" font-size="10.8" fill="#14532d">4. <tspan font-weight="bold">İdgam-ı Bila-Gunne (2 Harf):</tspan> ل ر (Gunnesiz)</text>\n  <text x="370" y="186" font-size="10.8" fill="#14532d">5. <tspan font-weight="bold">İklab (1 Harf):</tspan> ب (Mim\'e çevrilip gunneli okunur)</text>\n  <text x="370" y="208" font-size="10.8" font-weight="bold" fill="#166534">Toplam: 6 + 15 + 4 + 2 + 1 = 28 Arapça Hecâ Harfi</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İklab hem tek kelimede (أَنْبِئْهُمْ) hem de iki ayrı kelime arasında (مِنْ بَعْدِ) gerçekleşebilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
